        setAdded(true)
      }}>{unavailable ? 'Unavailable' : atLimit ? 'Stock limit reached' : 'Add to cart'}</button>
      <span role="status" className={styles.status}>{added ? 'Added to cart.' : ''}</span>
    </div>
  )
}
